/-- The exact family being counted, not a syntactic protocol family. -/
def compatibleDomains (F : X → Y → Bool) (t : ℕ) : Set (Set Y) :=
  {S | ∃ U : Set X, ∃ P : PartialProtocol X,
    P.cost ≤ t ∧ P.compatible F U = S}

