def generatedFeatureValue {Y : Type*} [DecidableEq Y] {q : Nat}
    (v : Fin q → Y) (feature : List (Nat × Y)) : ℚ :=
  if feature.all (fun p =>
      if h : p.1 < q then decide (v ⟨p.1, h⟩ = p.2) else false)
  then 1 else 0

