  let D := defaultCarrierCodecs n p₀ s q₁ q₂ w Q (k + 1)
  let c := seedRecursiveCodes n p₀ s q₁ q₂ w Q k
  let E : Code := .append (.ticket w) (taggedCode q₁ q₂ s c.2)
  let G : Code := graphRowsCode (V := Fin n) q₁ q₂ s c.1
  2 * D.2.maxLen + 2 + (Q + 1) +
