  ∀ p α, (Finset.univ.filter (fun i => σ i = p ∧ v i α = true)).card ≤ 1

def duplicatedFirstMatrix {a N₁ : ℕ} (ha : 2 ≤ a) (C₁ : FirstFamily a N₁) :
