  if aligned hs c then
    let α := (c.2 (firstBin s hs)).1
    if hi : vectors i α = true then
      c.1 (Fin.castAdd 1 (activeSlot vectors cap α ⟨i, hi⟩))
    else c.1 (Fin.last s)
