/-- The coordinates whose routed object is counted at the frontier node `u`. -/
def arrivalsAt (arr : Coord → FrontierArrival ι) (u : ι) : Finset Coord :=
  Finset.univ.filter (fun α => 0 < (arr α).hContrib u)

/-- The binary words of length `n`. -/
def blocks (n : ℕ) : Finset (List Bool) :=
  (Finset.univ : Finset (Fin n → Bool)).image (fun f => List.ofFn f)

/-- The length-`r` completions of a frontier node's route. -/
def extensions (r : ℕ) (p : List Bool) : Finset (List Bool) :=
  (blocks (r - p.length)).image (fun s => p ++ s)

/-- The witnesses split before reaching the frontier (`08:992--993`). -/
def splits (arr : Coord → FrontierArrival ι) : Finset Coord :=
  Finset.univ.filter (fun α => (arr α).isSplit = true)

/-- The witnesses that reach the frontier whole. -/
def unsplitWitnesses (arr : Coord → FrontierArrival ι) : Finset Coord :=
  Finset.univ.filter (fun α => (arr α).isUnsplitWitness = true)

/-- `W`, the coordinates carrying a witness object (`08:820--823`). -/
def witnesses (arr : Coord → FrontierArrival ι) : Finset Coord :=
  Finset.univ.filter (fun α => (arr α).isWitness = true)

theorem exists_child_two_mul {rep : Phys → Coord × Γ} {S₀ S₁ : Finset Phys}
    {α : Coord} {T : Finset Γ} (r : BobRouting rep S₀ S₁ α T) :
    T.card ≤ 2 * r.left.card ∨ T.card ≤ 2 * r.right.card

/-- One object per coordinate of the good set at the root. -/
def rootFamily [DecidableEq Coord] (H : Finset Coord) (T : Coord → Finset Γ) :
    RoutedFamily Coord Γ := fun α => if α ∈ H then some (T α) else none

theorem routedToken_support_card_ge {Γ : Type*} [Fintype Γ] {q₂ b₁ : ℕ}
    (t : RoutedToken Γ q₂ b₁) :
    lambdaAt q₂ b₁ t.depth * (Fintype.card Γ : ℝ) ≤ (t.support.card : ℝ)

theorem routingFloor_succ_le_of_two_mul (Γ : Type*) [Fintype Γ] {q₂ b₁ d m k : ℕ}
    (h : routingFloor Γ q₂ b₁ d ≤ m) (h2 : m ≤ 2 * k) :
    routingFloor Γ q₂ b₁ (d + 1) ≤ k

theorem unsplitWitness_density_gt_omega {q₂ b₁ d : ℕ} {T : Finset Γ}
    (hslack : RoutingSlack q₂ b₁) (hinv : routingBound q₂ b₁ d ≤ supportDensity T) :
    omegaRoute < supportDensity T

/-- **`eq:dense-source-row-gate` (`08:528--531`)**, `x_cap <= 1/(2s)`.
Transcribed as a predicate and never asserted. -/
def denseSourceRowGate (a b₀ s : ℕ) : Prop := xCap a b₀ ≤ 1 / (2 * (s : ℝ))

/-- The argmax set of a branch-count vector.  `08:586`. -/
def maxSet {s : ℕ} (ℓ : Fin s → ℕ) : Finset (Fin s) :=
  Finset.univ.filter fun j => ∀ k : Fin s, ℓ k ≤ ℓ j

