-- Full declaration, including proof; local bindings are part of the statement.
/-- **Aux A2 (`A:138`'s census readout of a supply).**  General. -/
theorem routedTriple_blockCount {r' t aSharp : ℕ} {x h : ℝ}
    {S : Finset Blk} {T : Finset Row} {K : Finset Col}
    (htr : RoutedTriple (Blk := Blk) (Col := Col) r' t aSharp x h S T K) :
    S.card = r' * RestrictionDatum.certifiedPt t := htr.2.1

-- Full declaration, including proof; local bindings are part of the statement.
/-- **Aux A1 (the row side of a supply is nonempty).**  General. -/
theorem routedTriple_rows_nonempty {r' t aSharp : ℕ} {x h : ℝ}
    {S : Finset Blk} {T : Finset Row} {K : Finset Col}
    (htr : RoutedTriple (Blk := Blk) (Col := Col) r' t aSharp x h S T K) :
    T.Nonempty := htr.1

theorem ExtensionCallFour.capacity_dvd {T R Rloc b₁ e r₂ r₃ : ℕ} {delta0 colDens : ℝ}
    (h : ExtensionCallFour T R Rloc b₁ e r₂ r₃ delta0 colDens) :
    (2 : ℕ) ^ T ∣ terminalCapacity (2 ^ r₃) (2 ^ r₂)

theorem ExtensionCallFour.one_le_r' {T R Rloc b₁ e r₂ r₃ : ℕ} {delta0 colDens : ℝ}
    (_h : ExtensionCallFour T R Rloc b₁ e r₂ r₃ delta0 colDens) :
    1 ≤ (2 : ℕ) ^ Rloc

theorem ExtensionCallFour.r'_le_r {T R Rloc b₁ e r₂ r₃ : ℕ} {delta0 colDens : ℝ}
    (h : ExtensionCallFour T R Rloc b₁ e r₂ r₃ delta0 colDens) :
    (2 : ℕ) ^ Rloc ≤ 2 ^ R

/-- **Aux A1a.**  Every member of `S` projects into `projSet J S`.  General. -/
theorem mem_projSet {J : Finset (Fin q)} {S : Finset (Fin q → Y)} {f : Fin q → Y}
    (hf : f ∈ S) : (fun i : ↥J => f i.1) ∈ projSet J S

/-- **Aux A1e (nonemptiness is preserved).**  General. -/
theorem projSet_nonempty {J : Finset (Fin q)} {S : Finset (Fin q → Y)}
    (h : S.Nonempty) : (projSet J S).Nonempty

theorem ExtensionCallThree.capacity_dvd {T R Rloc b₁ e r₂ r₃ ℓ : ℕ} {dcls colDens : ℝ}
    (h : ExtensionCallThree T R Rloc b₁ e r₂ r₃ ℓ dcls colDens) :
    (2 : ℕ) ^ T ∣ Kint (2 ^ r₃) (2 ^ ℓ) (2 ^ r₂)

theorem ExtensionCallThree.capacity_eq {T R Rloc b₁ e r₂ r₃ ℓ : ℕ} {dcls colDens : ℝ}
    (h : ExtensionCallThree T R Rloc b₁ e r₂ r₃ ℓ dcls colDens) :
    (2 : ℕ) ^ Rloc * 2 ^ T = Kint (2 ^ r₃) (2 ^ ℓ) (2 ^ r₂)

theorem ExtensionCallThree.r'_le_r {T R Rloc b₁ e r₂ r₃ ℓ : ℕ} {dcls colDens : ℝ}
    (h : ExtensionCallThree T R Rloc b₁ e r₂ r₃ ℓ dcls colDens) :
    (2 : ℕ) ^ Rloc ≤ 2 ^ R

/-- **`09:1449--1450`.**  "Let `u` be the least power of two at least
`8 s kappa/d_cls`", as the exponent of that least power. -/
noncomputable def dyadicCeilExp (x : ℝ) : ℕ := sInf {k : ℕ | x ≤ (2 : ℝ) ^ k}

/-- **`09:1402--1403`.**  "the number of nontemplate coordinates" of one tuple. -/
def nonTemplateCount (YT : Finset Y) (f : Fin u → Y) : ℕ :=
  (Finset.univ.filter (fun i => f i ∉ YT)).card

/-- **`09:1404--1405`.**  The set of template coordinates of one tuple. -/
def templateSet (YT : Finset Y) (f : Fin u → Y) : Finset (Fin u) :=
  Finset.univ.filter (fun i => f i ∈ YT)

NPCC.Protocol.bitHead.code:
/-- The high bit of a width-`k+1` code. -/
def Protocol.bitHead {k : ℕ} (w : Fin (2 ^ (k + 1))) : Bool :=
  decide (2 ^ k ≤ w.1)

NPCC.Protocol.prefixCodeAppend_left.code:
theorem prefixCodeAppend_left {t1 t2 : Nat}
    (c1 : Fin (2 ^ t1)) (c2 : Fin (2 ^ t2)) :
    (Protocol.prefixCodeAppend c1 c2).1 / 2 ^ t2 = c1.1

NPCC.Protocol.prefixCodeAppend_right.code:
theorem prefixCodeAppend_right {t1 t2 : Nat}
    (c1 : Fin (2 ^ t1)) (c2 : Fin (2 ^ t2)) :
