Workspace.ChungProductTheorem.proj.code:
/-- Projection of a set family `G` onto a subset `C`. -/
def proj {U : Type*} [DecidableEq U] (C : Finset U) (G : Finset (Finset U)) : Finset (Finset U) :=
  G.image (fun S => S ∩ C)

_private.Workspace.Induction.0.Workspace.code:
/-- Row-density exponent identity: `2^{a-3/8}·2^{-a} = 2^{-3/8}`. -/
private theorem rowdens_id (a : ℝ) :
    Real.rpow 2 (a - 3/8) * Real.rpow 2 (-a) = Real.rpow 2 (-3/8)

/-- Step-3 row density: `2^{k-3}·2^{3-k-a} = 2^{-a}`. -/
private theorem step3_rowdens (k : ℕ) (a : ℝ) :
    Real.rpow 2 ((k:ℝ)-3) * Real.rpow 2 (3-(k:ℝ)-a) = Real.rpow 2 (-a)

_private.Workspace.LogRankBound.0.Worksp.code:
/-- The if-encoding `Bool → ℝ` (`true ↦ 1`, `false ↦ 0`) is injective. -/
private lemma bool_if_inj :
    Function.Injective (fun b : Bool => if b then (1 : ℝ) else 0)

Workspace.Types.CommComplexity.Achievabl.code:
/-- The set of achievable communication costs for `f`: a natural number `c`
belongs to this set iff there exists a deterministic protocol `P` whose cost
(tree depth) is `c` and which computes `f`. -/
def AchievableCosts {X Y Z : Type*} (f : X → Y → Z) : Set ℕ :=
  { c : ℕ | ∃ P : Protocol X Y Z, P.cost = c ∧ Protocol.Computes P f }

Workspace.Types.Protocol.Protocol.cost.doc:
The cost of a protocol is the depth (height) of the tree: the maximum
number of bits exchanged along any root-to-leaf path. A leaf has cost `0`;
an internal node (either party) has cost `1 + max (cost l) (cost r)`.

Workspace.UpperBound.Protocol.comap_cost.code:
theorem Protocol.comap_cost {A A' B B' Z : Type*}
    (αA : A → A') (αB : B → B') (P : Protocol A' B' Z) :
    (Protocol.comap αA αB P).cost = P.cost

Workspace.UpperBound.Protocol.comap_eval.code:
theorem Protocol.comap_eval {A A' B B' Z : Type*}
    (αA : A → A') (αB : B → B') (P : Protocol A' B' Z) (a : A) (b : B) :
    (Protocol.comap αA αB P).eval a b = P.eval (αA a) (αB b)
